	var slice = make([]int64, 0)
	var notExisting = make([]int64, 0)
	err := b.
		Int64s("slice", &slice).
		Int64("id", &id).
		Int64("nr", &nr).
		String("texta", &texta).
		Int64s("notExisting", &notExisting).
		BindError()

	assert.NoError(t, err)
