		BindError()

	assert.EqualError(t, err, "code=400, message=failed to bind field value to int64, internal=strconv.ParseInt: parsing \"nope\": invalid syntax, field=id")
	assert.Nil(t, b.errors)
	assert.Nil(t, b.BindError())
}

